// ==========================================================
// Validación, Normalización y Deduplicación de Paquetes Mesh LoRa (v2.1)
// ==========================================================

const staticData = $getWorkflowStaticData('global');
if (!staticData.messageCache) {
  staticData.messageCache = {};
}

const now = Date.now();
const CACHE_TTL_MS = 30000; // Ventana de 30 segundos

// Limpieza periódica de caché antigua (> 60 segundos)
for (const key of Object.keys(staticData.messageCache)) {
  if (now - staticData.messageCache[key] > 60000) {
    delete staticData.messageCache[key];
  }
}

const results = [];

for (const item of $input.all()) {
  let payload = item.json;

  // Desempaquetar payload si viene encapsulado en message o data
  if (payload && payload.message !== undefined) {
    if (typeof payload.message === 'string') {
      try {
        payload = JSON.parse(payload.message);
      } catch (e) {
        payload = { text: payload.message, event_type: 'public' };
      }
    } else if (typeof payload.message === 'object' && payload.message !== null) {
      payload = payload.message;
    }
  } else if (payload && payload.data !== undefined) {
    if (typeof payload.data === 'string') {
      try {
        payload = JSON.parse(payload.data);
      } catch (e) {
        payload = { text: payload.data, event_type: 'public' };
      }
    }
  }

  if (!payload || typeof payload !== 'object') {
    continue;
  }

  // Filtrar paquetes salientes propios para evitar loops de eco
  if (payload.is_outgoing === true || payload.sender === 'local' || payload.sender_id === 'local') {
    continue;
  }

  let eventType = payload.event_type || 'public';
  if (payload.temperature_c !== undefined || payload.battery_pct !== undefined || payload.voltage_v !== undefined) {
    if (!payload.text) eventType = 'telemetry';
  }
  if (payload.event_type === 'rf_log') {
    eventType = 'rf_log';
  }

  const senderId = payload.sender_id || payload.sender || 'unknown';
  const senderName = payload.sender_name || senderId;
  const channelIdx = payload.channel_index !== undefined ? payload.channel_index : (payload.channel_idx !== undefined ? payload.channel_idx : 0);
  const text = (payload.text || payload.raw_text || '').trim();

  // Si no hay texto y no es telemetría/anuncio/log explícito, ignorar
  if (!text && eventType !== 'telemetry' && eventType !== 'node_advert' && eventType !== 'rf_log') {
    continue;
  }

  // Filtrar respuestas de bots para evitar bucles reflejados
  if (text.startsWith('[Eco ') || text.startsWith('[Status ') || text.startsWith('[ACK') || text.startsWith('📡 ') || text.startsWith('⛔ ') || text.startsWith('📖 ') || text.startsWith('⏰ ') || text.startsWith('📅 ') || text.startsWith('🏓 ')) {
    continue;
  }

  // Generar hash para deduplicación
  const msgKey = `${eventType}_${senderId}_${channelIdx}_${text}`;

  let isDuplicate = false;
  if (text.length > 0) {
    if (staticData.messageCache[msgKey] && (now - staticData.messageCache[msgKey] < CACHE_TTL_MS)) {
      isDuplicate = true;
    } else {
      staticData.messageCache[msgKey] = now;
    }
  }

  results.push({
    json: {
      ...payload,
      event_type: eventType,
      sender_id: senderId,
      sender_name: senderName,
      channel_index: channelIdx,
      text: text,
      is_duplicate: isDuplicate,
      processed_at: new Date().toISOString()
    }
  });
}

return results;

// ==========================================================
// Procesador de Canal Público (Canal 0)
// Comandos: /time, /date, /datetime, /ping, /help, /nodes
// ==========================================================

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = (msg.text || '').trim();
  if (!rawText || rawText.startsWith('[Eco ') || rawText.startsWith('[Status ')) {
    continue;
  }

  const lower = rawText.toLowerCase();
  const senderName = msg.sender_name || msg.sender_id || 'Nodo';

  const now = new Date();
  let replyText = '';

  if (lower === '/time') {
    replyText = `⏰ Hora actual: ${now.toTimeString().split(' ')[0]} UTC`;
  } else if (lower === '/date') {
    replyText = `📅 Fecha actual: ${now.toISOString().split('T')[0]}`;
  } else if (lower === '/datetime') {
    replyText = `📅⏰ Fecha y Hora: ${now.toISOString().replace('T', ' ').substring(0, 19)} UTC`;
  } else if (lower === '/ping') {
    replyText = `🏓 Pong desde n8n Bridge! (Nodo: ${senderName})`;
  } else if (lower === '/help') {
    replyText = `📖 Comandos MeshCore:\n/time - Hora UTC\n/date - Fecha\n/ping - Comprobar enlace\n/status - Estado del nodo\n/admin - Comandos admin`;
  } else {
    replyText = `[Eco Pub] ${senderName}: "${rawText}"`;
  }

  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_pub_${Date.now()}`,
      to: 'broadcast',
      channel_index: 0,
      text: replyText
    }
  });
}

return results;

// ==========================================================
// Procesador de Canales Secundarios Cifrados (Canal 1..7)
// ==========================================================

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = (msg.text || '').trim();
  if (!rawText || rawText.startsWith('[Eco ')) {
    continue;
  }
  const senderName = msg.sender_name || msg.sender_id || 'Nodo';
  const chIdx = msg.channel_index || 1;

  const replyText = `[Eco Ch ${chIdx}] ${senderName}: "${rawText}"`;

  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_chan_${Date.now()}`,
      to: 'broadcast',
      channel_index: chIdx,
      text: replyText
    }
  });
}

return results;

// ==========================================================
// Procesador de Mensajes Directos (DM), Admin y Repetidores
// ==========================================================

const ADMIN_WHITELIST = ['admin_master', 'heltec_admin', 'rak_admin', 'lilygo_admin', '8f3a12bc', 'feedfacecafe0001'];

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = (msg.text || '').trim();
  if (!rawText || rawText.startsWith('[Eco ') || rawText.startsWith('[Status ') || rawText.startsWith('⛔ ')) {
    continue;
  }
  const lower = rawText.toLowerCase();
  const senderId = msg.sender_id || 'unknown';
  const senderName = msg.sender_name || senderId;
  const isAdmin = ADMIN_WHITELIST.includes(senderId) || ADMIN_WHITELIST.includes(senderName);

  if (lower === '/status') {
    const rssiInfo = msg.metrics && msg.metrics.rssi ? ` | RSSI: ${msg.metrics.rssi} dBm` : '';
    const replyText = `[Status MeshCore v2.1]\nBridge: Online\nNodo: ${senderName}${rssiInfo}\nHora: ${new Date().toISOString().substring(11, 19)} UTC`;

    results.push({
      json: {
        topic: 'meshcore/tx',
        request_id: `n8n_status_${Date.now()}`,
        to: senderId,
        channel_index: 0,
        text: replyText
      }
    });
    continue;
  }

  if (lower.startsWith('/admin')) {
    if (!isAdmin) {
      results.push({
        json: {
          topic: 'meshcore/tx',
          request_id: `n8n_denied_${Date.now()}`,
          to: senderId,
          channel_index: 0,
          text: '⛔ Acceso denegado: Nodo no autorizado para comandos administrativos.'
        }
      });
      continue;
    }

    const parts = rawText.split(' ').filter(p => p.length > 0);
    const subCmd = (parts[1] || '').toLowerCase();

    // Caso 1: Comandos a Repetidores Remotos (/admin repeater <node_id> <cmd>)
    if (subCmd === 'repeater' && parts[2] && parts[3]) {
      const targetRepeater = parts[2];
      const repCmd = parts.slice(3).join(' ');
      results.push({
        json: {
          topic: `meshcore/admin/repeater/${targetRepeater}/cmd`,
          request_id: `n8n_rep_${Date.now()}`,
          action: repCmd,
          target_node: targetRepeater
        }
      });
      results.push({
        json: {
          topic: 'meshcore/tx',
          request_id: `n8n_ack_${Date.now()}`,
          to: senderId,
          text: `📡 Enviando comando "${repCmd}" a repetidor ${targetRepeater}...`
        }
      });
      continue;
    }

    // Caso 2: Comandos Locales
    let actionName = null;
    let ackNotice = '';
    let extraData = {};

    if (subCmd === 'get_config' || subCmd === 'config') {
      actionName = 'get_config';
      ackNotice = '⚙️ Consultando configuración del nodo...';
    } else if (subCmd === 'list_nodes' || subCmd === 'nodes') {
      actionName = 'list_nodes';
      ackNotice = '📖 Consultando registro de nodos activos...';
    } else if (subCmd === 'set_name' && parts[2]) {
      actionName = 'set_name';
      extraData.name = parts.slice(2).join(' ');
      ackNotice = `✏️ Cambiando nombre a: ${extraData.name}`;
    } else if (subCmd === 'set_power' && parts[2]) {
      actionName = 'set_tx_power';
      extraData.power = parseInt(parts[2], 10);
      ackNotice = `📶 Ajustando potencia TX a: ${extraData.power} dBm`;
    } else if (subCmd === 'reboot') {
      actionName = 'reboot';
      ackNotice = '🔄 Reiniciando radio local...';
    } else {
      ackNotice = '❓ Comando admin no reconocido. Uso: /admin [config|nodes|set_name <n>|set_power <p>|repeater <id> <cmd>]';
    }

    results.push({
      json: {
        topic: 'meshcore/tx',
        request_id: `n8n_adm_ack_${Date.now()}`,
        to: senderId,
        channel_index: 0,
        text: ackNotice
      }
    });

    if (actionName) {
      results.push({
        json: {
          topic: 'meshcore/admin/cmd',
          request_id: `n8n_adm_${Date.now()}`,
          action: actionName,
          ...extraData
        }
      });
    }
    continue;
  }

  // Eco DM
  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_dm_${Date.now()}`,
      to: senderId,
      channel_index: 0,
      text: `[Eco DM] Recibido: "${rawText}"`
    }
  });
}

return results;

// ==========================================================
// Procesador de Telemetría Ambiental y Sensores CayenneLPP
// ==========================================================

const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const sender = data.sender || data.sender_id || 'unknown';
  const temp = data.temperature_c !== undefined ? data.temperature_c : null;
  const hum = data.humidity_pct !== undefined ? data.humidity_pct : null;
  const press = data.pressure_hpa !== undefined ? data.pressure_hpa : null;
  const batt = data.battery_pct !== undefined ? data.battery_pct : (data.battery !== undefined ? data.battery : null);
  const volt = data.voltage_v !== undefined ? data.voltage_v : null;
  const gps = data.gps || null;

  let isAlert = false;
  let alertMsg = '';

  // Detección de umbrales críticos
  if (batt !== null && batt < 20) {
    isAlert = true;
    alertMsg += `⚠️ Batería baja (${batt}%) en nodo ${sender}. `;
  }
  if (temp !== null && temp > 45.0) {
    isAlert = true;
    alertMsg += `🔥 Temperatura alta (${temp}°C) en nodo ${sender}. `;
  }

  results.push({
    json: {
      event_type: 'telemetry_processed',
      sender: sender,
      temperature: temp,
      humidity: hum,
      pressure: press,
      battery_pct: batt,
      voltage_v: volt,
      gps: gps,
      is_alert: isAlert,
      alert_text: alertMsg,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

// ==========================================================
// Procesador de Anuncios de Nodos (Node Discovery)
// ==========================================================

const results = [];
for (const item of $input.all()) {
  const data = item.json;
  results.push({
    json: {
      event_type: 'node_discovered',
      node_id: data.sender || data.sender_id,
      node_name: data.sender_name || 'Nuevo Nodo',
      hops: data.hops || 0,
      discovered_at: new Date().toISOString()
    }
  });
}
return results;

// ==========================================================
// Procesador de Packet Sniffer RF (0x88 LOG_DATA)
// ==========================================================

const results = [];
for (const item of $input.all()) {
  const data = item.json;
  results.push({
    json: {
      event_type: 'rf_traffic_logged',
      route_type_id: data.route_type_id,
      payload_type_id: data.payload_type_id,
      bytes: data.byte_length || 0,
      captured_at: new Date().toISOString()
    }
  });
}
return results;
